// SettingsView.tsx
// Three stacked cards:
//   (A) Upload Limits     — macro-card style, reflects live usage
//   (C) Personal Info     — inputs with public/private toggle, auto-saves to LS
//   (D) Supported Formats — static reference table

import React, { useEffect, useState } from "react";
import {
  FaUser, FaBuilding, FaPhone, FaEnvelope,
  FaCheckCircle, FaExclamationTriangle, FaTimesCircle,
} from "react-icons/fa";
import { Topbar } from "./CmsShell";
import {
  UPLOAD_LIMITS,
  useCmsSettings,
  type PersonalField,
  type PersonalInfoKey,
} from "./settings";
import { bravoRoofingImageApi } from "./imageApi";
import { useImageSyncQueue } from "./useImageSyncQueue";

// ── Upload Limits card ─────────────────────────────────────────────────────
// Layout intentionally mirrors the macro-tracker reference Nate shared:
//   • one segmented bar at the top (one colored band per metric, sized to usage)
//   • a stack of clean metric rows below — title/value on the left,
//     "Remaining" + value on the right. No per-row progress bars.
const UploadLimitsCard: React.FC<{ totalImages: number; activeUploads: number }> = ({
  totalImages, activeUploads,
}) => {
  const totalPct      = Math.min(100, (totalImages   / UPLOAD_LIMITS.maxTotalImages)       * 100);
  const concurrentPct = Math.min(100, (activeUploads / UPLOAD_LIMITS.maxConcurrentUploads) * 100);
  const totalRemaining      = Math.max(0, UPLOAD_LIMITS.maxTotalImages       - totalImages);
  const concurrentRemaining = Math.max(0, UPLOAD_LIMITS.maxConcurrentUploads - activeUploads);

  // Colour graduation: green → amber → red as the metric approaches its cap.
  const totalColor      = totalPct      >= 100 ? "#ef4444" : totalPct      >= 80 ? "#f59e0b" : "#22c55e";
  const concurrentColor = concurrentPct >= 100 ? "#ef4444" : concurrentPct >= 67 ? "#f59e0b" : "#3b82f6";

  // Each metric owns half of the top bar's width. Its own fill = usage %.
  const totalSegment      = (totalPct      / 100) * 50;
  const concurrentSegment = (concurrentPct / 100) * 50;

  return (
    <div className="settings-card">
      <div className="settings-card__header">
        <h3 className="settings-card__title">Upload Limits</h3>
        <p className="settings-card__sub">
          Frontend-enforced. Database-backed limits coming later — this UI won't change when they do.
        </p>
      </div>

      {/* Segmented usage bar (mirrors the macro reference) */}
      <div className="usage-bar">
        <div className="usage-bar__seg" style={{ width: `${totalSegment}%`,      background: totalColor }} />
        <div className="usage-bar__seg" style={{ width: `${concurrentSegment}%`, background: concurrentColor }} />
      </div>

      <div className="limit-rows">
        <LimitMetric
          color={totalColor}
          title="Total Images"
          value={`${totalImages} / ${UPLOAD_LIMITS.maxTotalImages}`}
          remaining={totalRemaining}
        />
        <LimitMetric
          color={concurrentColor}
          title="Concurrent Uploads"
          value={`${activeUploads} / ${UPLOAD_LIMITS.maxConcurrentUploads}`}
          remaining={concurrentRemaining}
        />
      </div>
    </div>
  );
};

const LimitMetric: React.FC<{
  color: string;
  title: string;
  value: string;
  remaining: number;
}> = ({ color, title, value, remaining }) => (
  <div className="limit-metric">
    <div className="limit-metric__left">
      <span className="limit-metric__swatch" style={{ background: color }} />
      <div className="limit-metric__text">
        <div className="limit-metric__title">{title}</div>
        <div className="limit-metric__value">{value}</div>
      </div>
    </div>
    <div className="limit-metric__right">
      <div className="limit-metric__label">Remaining</div>
      <div className="limit-metric__rem">{remaining}</div>
    </div>
  </div>
);

// ── Personal Info card ─────────────────────────────────────────────────────
const PersonalInfoCard: React.FC<{
  info: ReturnType<typeof useCmsSettings>["settings"]["personalInfo"];
  onChange: (key: PersonalInfoKey, patch: Partial<PersonalField>) => void;
}> = ({ info, onChange }) => {
  const fields: Array<{
    key: PersonalInfoKey; label: string; placeholder: string;
    icon: React.ReactNode; type?: string;
  }> = [
    { key: "name",         label: "Name",          placeholder: "Your full name",    icon: <FaUser size={13} /> },
    { key: "businessName", label: "Business Name", placeholder: "Acme Roofing Co.",  icon: <FaBuilding size={13} /> },
    { key: "phone",        label: "Phone",         placeholder: "(555) 123-4567",    icon: <FaPhone size={13} />, type: "tel" },
    { key: "email",        label: "Email",         placeholder: "you@example.com",   icon: <FaEnvelope size={13} />, type: "email" },
  ];

  return (
    <div className="settings-card">
      <div className="settings-card__header">
        <h3 className="settings-card__title">Personal Info</h3>
        <p className="settings-card__sub">This info is private unless you enable public.</p>
      </div>
      <div className="info-grid">
        {fields.map(f => {
          const field = info[f.key];
          return (
            <div key={f.key} className="info-field">
              <div className="info-field__label">{f.icon}<span>{f.label}</span></div>
              <input
                type={f.type ?? "text"}
                className="info-field__input"
                placeholder={f.placeholder}
                value={field.value}
                onChange={e => onChange(f.key, { value: e.target.value })}
              />
              <label className="info-field__toggle">
                <input
                  type="checkbox"
                  checked={field.isPublic}
                  onChange={e => onChange(f.key, { isPublic: e.target.checked })}
                />
                <span className="info-field__toggle-slider" />
                <span className={`info-field__toggle-label ${field.isPublic ? "is-public" : ""}`}>
                  Is currently {field.isPublic ? "public" : "private"}
                </span>
              </label>
            </div>
          );
        })}
      </div>
    </div>
  );
};

// ── Supported Formats card ─────────────────────────────────────────────────
type FormatStatus = "ok" | "warn" | "bad";
const FORMATS: Array<{ name: string; status: FormatStatus; notes: string }> = [
  { name: "JPG / JPEG", status: "ok",   notes: "Best" },
  { name: "PNG",        status: "ok",   notes: "Transparency" },
  { name: "WebP",       status: "ok",   notes: "Best modern" },
  { name: "AVIF",       status: "warn", notes: "Slow, limited" },
  { name: "GIF",        status: "warn", notes: "First frame only" },
  { name: "HEIC",       status: "bad",  notes: "Mostly broken" },
  { name: "SVG",        status: "warn", notes: "Unpredictable" },
];

const FormatsCard: React.FC = () => (
  <div className="settings-card">
    <div className="settings-card__header">
      <h3 className="settings-card__title">Supported Formats</h3>
      <p className="settings-card__sub">Stick to JPG, PNG, or WebP for reliable results.</p>
    </div>
    <table className="formats-table">
      <thead>
        <tr><th>Format</th><th>Works</th><th>Notes</th></tr>
      </thead>
      <tbody>
        {FORMATS.map(f => (
          <tr key={f.name}>
            <td><span className="format-name">{f.name}</span></td>
            <td>
              {f.status === "ok"   && <span className="format-pill format-pill--ok"><FaCheckCircle size={11} /> Supported</span>}
              {f.status === "warn" && <span className="format-pill format-pill--warn"><FaExclamationTriangle size={11} /> Partial</span>}
              {f.status === "bad"  && <span className="format-pill format-pill--bad"><FaTimesCircle size={11} /> Unreliable</span>}
            </td>
            <td className="formats-table__notes">{f.notes}</td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

// ── Main view ──────────────────────────────────────────────────────────────
export const SettingsView: React.FC<{ onMenuToggle: () => void }> = ({ onMenuToggle }) => {
  const { settings, updatePersonal } = useCmsSettings();
  const { getUploads } = useImageSyncQueue();

  const [totalImages, setTotalImages]     = useState(0);
  const [activeUploads, setActiveUploads] = useState(0);

  // Total images = CMS-uploaded entries in files.json (static built-ins don't count).
  useEffect(() => {
    let cancelled = false;
    bravoRoofingImageApi
      .fetchFiles()
      .then(records => {
        if (cancelled) return;
        setTotalImages(records.filter(r => !r.isStatic).length);
      })
      .catch(() => { /* silent — card still renders with 0 */ });
    return () => { cancelled = true; };
  }, []);

  // Poll active upload count so the card stays live while uploads complete.
  useEffect(() => {
    const tick = () => setActiveUploads(getUploads().length);
    tick();
    const interval = setInterval(tick, 2000);
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <>
      <style>{styles}</style>
      <div className="view-wrap">
        <Topbar title="Settings" sub="Limits, personal info and supported formats" onMenuToggle={onMenuToggle} />
        <UploadLimitsCard totalImages={totalImages} activeUploads={activeUploads} />
        <PersonalInfoCard info={settings.personalInfo} onChange={updatePersonal} />
        <FormatsCard />
      </div>
    </>
  );
};

